@startuml

class Product {
  + Name : string
  + Description : string
  + NetPrice : double
}

class Manufacturer {
  + Name : string
}

class Country {
  + Name : string
  + VATRate : float
  + Currency : string
  + ConversionRate : double
}

class Representative {
  + FirstName : string
  + LastName : string
  + SocialSecurityNumber : string
  + TelephoneNumber : string
  + EmailAddress : string
}

class Customer {
  + Name : string
  + Address : string
  + TelephoneNumber : string
  + EmailAddress : string
}

class Order {
  + OrderID : string
  + Quantity : int
  + OrderDate : date
  + DesiredDeliveryDate : date
}

Manufacturer "1" -- "*" Product
Product "*" -- "1" Country : manufactured in
Product "*" -- "*" Country : available in
Representative "1" -- "1" Country : responsible for
Representative "1" -- "*" Order : places
Customer "1" -- "*" Order : places
Customer "*" -- "*" Country : resells in

@enduml

